'use strict';

const { Response }      = require('./Response');
const { AuthError }     = require('./errors/AuthError');
const { ApiError }      = require('./errors/ApiError');
const { StrongmbError } = require('./errors/StrongmbError');

const LIVE_URL    = 'https://api.strongmb.ng/v1/';
const SANDBOX_URL = 'https://sandbox.api.strongmb.ng/v1/';

class Client {
    constructor(apiKey, sandbox = false) {
        this._baseUrl = sandbox ? SANDBOX_URL : LIVE_URL;
        this._headers = {
            'Authorization': `Bearer ${apiKey}`,
            'Accept':        'application/json',
            'Content-Type':  'application/json',
        };
    }

    get(endpoint) {
        return this._request('GET', endpoint);
    }

    post(endpoint, body = {}) {
        return this._request('POST', endpoint, body);
    }

    async _request(method, endpoint, body = null) {
        const url     = this._baseUrl + endpoint;
        const options = { method, headers: this._headers };

        if (body !== null) {
            options.body = JSON.stringify(body);
        }

        let res;
        try {
            res = await fetch(url, options);
        } catch (err) {
            throw new StrongmbError('Network error: ' + err.message);
        }

        let data;
        try {
            data = await res.json();
        } catch {
            throw new StrongmbError('Invalid JSON response from API.');
        }

        if (res.status === 401) {
            throw new AuthError(data.message ?? 'Unauthorized.', data);
        }

        if (res.status >= 400) {
            throw new ApiError(
                data.message ?? 'API error.',
                data.metadata?.code ?? 'ERR_UNKNOWN',
                res.status,
                data,
            );
        }

        return new Response(data, res.status);
    }
}

module.exports = { Client };
